// #Sireum

package factory_flow.Factory_Flow

import org.sireum._
import art._
import factory_flow._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait MaterialCorrelationQualifier_Api {
  def id: Art.BridgeId
  def materialObservation_Id : Art.PortId
  def admission_Id : Art.PortId
  def materialFact_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var materialFact: Factory_Flow.MaterialFact = $

  def put_materialFact(value : Factory_Flow.MaterialFact) : Unit = {
    Contract(
      Modifies(materialFact),
      Ensures(
        materialFact == value
      )
    )
    Spec {
      materialFact = value
    }

    Art.putValue(materialFact_Id, Factory_Flow.MaterialFact_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class MaterialCorrelationQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val materialObservation_Id : Art.PortId,
  val admission_Id : Art.PortId,
  val materialFact_Id : Art.PortId) extends MaterialCorrelationQualifier_Api

@datatype class MaterialCorrelationQualifier_Operational_Api (
  val id: Art.BridgeId,
  val materialObservation_Id : Art.PortId,
  val admission_Id : Art.PortId,
  val materialFact_Id : Art.PortId) extends MaterialCorrelationQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var materialObservation: Factory_Flow.MaterialHandoffObservation = $

  def get_materialObservation() : Option[Factory_Flow.MaterialHandoffObservation] = {
    Contract(
      Ensures(
        Res == Some(materialObservation)
      )
    )
    val value : Option[Factory_Flow.MaterialHandoffObservation] = Art.getValue(materialObservation_Id) match {
      case Some(Factory_Flow.MaterialHandoffObservation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port materialObservation.  Expecting 'Factory_Flow.MaterialHandoffObservation_Payload' but received ${v}")
        None[Factory_Flow.MaterialHandoffObservation]()
      case _ => None[Factory_Flow.MaterialHandoffObservation]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var admission: Factory_Flow.AdmissionFact = $

  def get_admission() : Option[Factory_Flow.AdmissionFact] = {
    Contract(
      Ensures(
        Res == Some(admission)
      )
    )
    val value : Option[Factory_Flow.AdmissionFact] = Art.getValue(admission_Id) match {
      case Some(Factory_Flow.AdmissionFact_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port admission.  Expecting 'Factory_Flow.AdmissionFact_Payload' but received ${v}")
        None[Factory_Flow.AdmissionFact]()
      case _ => None[Factory_Flow.AdmissionFact]()
    }
    return value
  }
}
